from pathlib import Path
import re
errors = []
for page in Path('docs').rglob('*.md'):
    for target in re.findall(r'\]\(([^)]+)\)', page.read_text()):
        if '://' in target:
            continue
        name, _, anchor = target.partition('#')
        dest = page.parent / name if name else page
        if not dest.is_file():
            errors.append(f'{page}: missing {target}')
        elif anchor:
            headings = [re.sub(r'[^\w -]', '', h.lower()).replace(' ', '-') for h in re.findall(r'^#+ (.+)$', dest.read_text(), re.M)]
            if anchor not in headings:
                errors.append(f'{page}: missing anchor {target}')
if errors:
    raise SystemExit('\n'.join(errors))
print('All documentation file links and heading anchors resolve.')
